  ('11adabd6-206f-4cc2-a22d-41ae87b364bf', '78a7ec2f-73df-4efe-b560-2ff3d8b0bf7c', 10,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Regulatie van ecosystemen"}]'::jsonb,
